const onCenter = () => {
  if (serverStt.isRecording) {
    // Stop recording and send to server STT
    void (async () => {
      const text = await serverStt.stopRecording()
      if (text) voice.injectTranscript(text)
    })()
    return
  }
  if (needsFallback) {
    // Start push-to-talk recording
    void serverStt.startRecording()
    return
