            mentorId={tutor.id}
            state={orbState}
            reducedMotion={reduceMotion}
            onTap={onCenter}
            ariaLabel={micLabel}
          />
        </div>

        <div className="v-state" aria-live="polite">
          <span className={`sv sv-${voice.state}`}>
            {serverStt.isRecording
              ? (lang === 'ar' ? '⏺ سجّل — ارفع الإصبع للإرسال' : '⏺ Recording… release to send')
              : serverStt.isSending
                ? (lang === 'ar' ? '⏳ جارٍ التعرف...' : '⏳ Transcribing…')
                : statusText}
          </span>
        </div>

        {hint && <div className="v-note" role="status">{hint}</div>}

        <div className="v-sub">
          <span className={`sb sb-${voice.state}`}>
            {serverStt.isRecording
              ? (lang === 'ar' ? 'ارفع الإصبع لإرسال التسجيل' : 'Release to send')
              : needsFallback
                ? (lang === 'ar' ? 'اضغط باستمرار على المايك للتسجيل، ثم ارفع الإصبع' : 'Hold the mic to record, then release')
                : MOCKUP_VOICE_SUB[voice.state][lang]}
          </span>
        </div>

        <div className="eq" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span></div>

        <div className={`vc vc-${voice.state}`} aria-live="polite">
          {voice.state === 'speaking' ? (
            <div className="vc-row vc-agent">
              <span className="vc-text" dir={messageDir(lastAgent)}>{lastAgent}</span>
              <span className="vc-fade" aria-hidden="true" />
            </div>
          ) : voice.state === 'processing' ? (
            <div className="vc-row vc-user">
              <span className="vc-text" dir={messageDir(lastUser)}>{lastUser}</span>
              <span className="dots"><i></i><i></i><i></i></span>
            </div>
          ) : voice.state === 'interrupted' ? (
            <div className="vc-row vc-user">
              <span className="vc-text" dir={messageDir(lastUser)}>{lastUser}<span className="caret" /></span>
            </div>
          ) : voice.state === 'listening' ? (
            <div className="vc-row vc-user">
              <span className="vc-text" dir={messageDir(lastUser)}>{lastUser ? lastUser : '—'}<span className="caret" /></span>
            </div>
          ) : (
            <div className="vc-row vc-idle">
              <span className="vc-text">—</span>
            </div>
          )}
        </div>

        {err && <div className="v-err">{err}</div>}
      </div>

      <footer className="v-bottom">
        <div className="v-dock">
          <button type="button" className="v-keyboard" onClick={onClose} aria-label={ui.voiceKeyboard}>
            <IconKeyboard size={20} />
            <span className="v-kbd-label">{ui.voiceTypeInstead}</span>
          </button>

          <button
            type="button"
            className="v-mic"
            data-recording={serverStt.isRecording ? 'true' : undefined}
            onPointerDown={onMicPointerDown}
            onPointerUp={onMicPointerUp}
            onPointerCancel={onMicPointerUp}
            onClick={onMicClick}
            disabled={(!voice.supported && !needsFallback && !serverStt.isRecording) || (!studentSafe(voice) && !needsFallback)}
            aria-label={micLabel}
          >
            {stopActive ? <span className="stop-sq"></span> : <IconMic size={28} />}
          </button>

          <button type="button" className="v-end" onClick={() => { voice.stop(); onClose() }} aria-label={ui.voiceEnd}>
            <IconStop size={15} />
            <span className="v-end-label">{ui.voiceEnd}</span>
          </button>
        </div>
      </footer>
    </div>
  )
  // Portal to <body> so the live surface truly fills the app viewport and the
  // Copilot chat / dashboard can never bleed through.
  return typeof document === 'undefined' ? surface : createPortal(surface, document.body)
}

// Guard-local helper: the mic/stop control stays usable when the engine has an
// error so the user can retry (starts a fresh session from idle), but is locked
// only when speech recognition cannot run at all.
function studentSafe(voice: VoiceSessionApi): boolean {
  return !voice.error || voice.state === 'idle'
}

parts.text:
Now I have the full picture. Real issues in the client voice flow:

**Bug 1 — hold/release race (probable "never responds"):** The window-level release handlers are bound in a `useEffect` keyed on `serverStt.isRecording`. The sequence for a tap or short hold:
1. pointerdown (mic) → startRecording() async (await getUserMedia)
2. pointerup within ~100-400ms → onMicPointerUp: isRecording still false → nothing. 
3. getUserMedia resolves → isRecording=true → effect binds window listeners, but the pointerup event already passed.
Result: recording stays active with NO future pointerup to end it → stuck "⏺ Recording… release to send" until the user taps again (second tap: onMicPointerDown → `if (serverStt.isRecording) return` → pointer up → isRecording true → submit → submitRef → stopRecording → STT → reply). So a two-tap sequence eventually works, but a single natural tap/hold leaves it stuck recording → mentor "never responds". THIS is very likely what the user hits: they tap/hold briefly, release, nothing happens (no transcript submitted); second press works only if they hold again. Confusing and flaky.

Fix: bind the window release handlers ONCE at mount (not state-gated), armed by pointerHeldRef:
- `releaseArmedRef` set true in onMicPointerDown.
- Window pointerup/touchend/pointercancel: if releaseArmedRef true → releaseArmedRef=false → submitRef.current() (stopRecording no-ops if not recording).
- onMicPointerUp: if pointerHeldRef current → also submit (it will if recording true; stopRecording no-ops otherwise).
This way, however quickly the getUserMedia resolves, the release action is remembered and fired as soon as the user lifts the finger anywhere. If getUserMedia is slow and user already lifted, releaseArmedRef stays true until... we should also clear armed after a short timeout? No — if user lifts before recording starts, we should submit the moment recording is ready. So hold the submission until recording is actually active: schedule a check. Simpler robust approach:
- On pointerup, if recording not yet started, arm a "pending submit" that fires right after recording starts (e.g., in startRecording's completion). Add `pendingSubmitRef` — after setIsRecording(true), if pendingSubmitRef true → clear + submitRef…

Hmm, complexity. Cleaner: in startRecording completion, if pointerHeldRef is false (they already lifted) → auto-submit immediately. That guarantees a quick tap still produces a turn (with whatever was captured —possibly too short → "Didn't catch that"). And in onMicPointerUp, if isRecording already true → submit. Also bind window handlers once.

Actually the simplest reliable pattern:
- onMicPointerDown: pointerHeldRef=true; if needsFallback → await startRecording(); if after start pointerHeldRef is FALSE (released during permission/getUserMedia) AND recording just started → immediately submit.
- onMicPointerUp: pointerHeldRef=false; if isRecordingRef... we don't have direct access, but serverStt.isRecording state—stale in handler. Use the armed approach: just always call submitRef.current() on pointer up IF we had armed a recording this gesture AND recording is (or becomes) active.

I'll implement:
```
const releaseArmedRef = useRef(false)
const onMicPointerDown = () => {
  if (serverStt.isSending) return
  pointerHeldRef.current = true
  releaseArmedRef.current = true
  setHint(null)
  if (serverStt.isRecording) return
  if (needsFallback) void serverStt.startRecording()
}
const submitIfArmed = () => {
  if (!releaseArmedRef.current) return
  releaseArmedRef.current = false
  void submitRef.current()
}
window listeners bound ONCE on mount → submitIfArmed
onMicPointerUp = () => { pointerHeldRef.current = false; submitIfArmed() }
```
And in startRecording (hook) completion, add: if the gesture lifted before recording became active, we still rely on window pointerup→submitIfArmed→stopRecording. But that pointerup ALREADY happened before recording started → no later event. So nothing fires afterward → stuck again.

So the hook needs a "pending release" mechanism: after recording becomes active, if a release was requested while pending, stop immediately. I'll add inside the hook:
```
const releaseRequestedRef = useRef(false)
```
The hook exposes `requestStop()` — but keep it simple: add an optional completion check via a callback. The component can set `pendingSubmitRef` before calling startRecording:
```
const pendingSubmitRef = useRef(false)
onMicPointerDown:
 pointerHeldRef=true; pendingSubmitRef.current=false
 void serverStt.startRecording().then(() => {
   if (pendingSubmitRef.current) submitRef.current()  // lifted during startup
 })
onMicPointerUp:
 pointerHeldRef.current=false
 pendingSubmitRef.current = serverStt.isRecording ? false : true  // wait for start
```
If isRecording was already true at pointerup → placeholder... handle: `if (serverStt.isRecording) void submitRef.current(); else pendingSubmitRef.current = true`.

Hmm but `serverStt.isRecording` in the handler closure is the CURRENT render's state — staleness risk is low since handlers re-created per render (component re-renders when isRecording changes), so onMicPointerUp in the latest render sees current value. Good.

And window release (bound once): same logic — but the once-bound closure captures stale state; use refs. Use a ref mirroring isRecording: `recordingRef`. The hook can expose... simpler: keep window handlers keyed on state (as today) BUT ALSO bound immediately and use releaseArmedRef + a getter. To avoid overengineering, I'll do:

- Bind window handlers in the `useEffect` keyed on `[serverStt.isRecording]` as today (so release during active recording is caught), PLUS
- In `onMicPointerUp`/`onMicClick` handle the pending case.

The main fix that virtually eliminates the stuck case: **in startRecording completion, if the user already released (pointerHeldRef false + releaseArmedRef still true), auto-submit.** Because the most common stuck scenario is: user pressed, released before getUserMedia resolved.

Let me restructure minimally:

Component:
```
const releaseArmedRef = useRef(false)   // armed by pointerdown; consumed by any release

onMicPointerDown:
  if (serverStt.isSending) return
  pointerHeldRef.current = true
  releaseArmedRef.current = true
  setHint(null)
  if (serverStt.isRecording) return
  if (needsFallback) void serverStt.startRecording().then(() => {
    // started; if the user already released during the async setup, submit now
    if (!pointerHeldRef.current && releaseArmedRef.current) submitRef.current()
  })

onMicPointerUp = () => {
  pointerHeldRef.current = false
  if (releaseArmedRef.current) {
    releaseArmedRef.current = false
    if (serverStt.isRecording) void submitRef.current()
  }
}
```
Window release effect: keep keyed on isRecording, but the handler checks releaseArmedRef (consume it) and submits. For the mid-recording release this works. And if user lifts BEFORE recording starts, the pending-submit in startRecording().then covers it. Two paths, both via releasing the finger. pointerhint.

Actually wait, in the window effect's `release`, currently no pointerHeld guard; it fires on ANY pointerup anywhere while recording (good — release anywhere). Keep but replace body with armed-check:
```
const release = () => { if (releaseArmedRef.current) { releaseArmedRef.current = false; void submitRef.current() } }
```
But careful: the window effect binds when isRecording becomes true. If recording is already active, pointerup → release. If the user pressed and got recording then released → works (today's behavior). For the stale case (released during startup), the `.then` covers it. 

Edge: after submit consumes armed, subsequent stray pointerup while NEXT recording? armed only set on pointerdown. Fine. Note the window listeners only exist while isRecording (deps), so stray release won't submit a non-recording state. Good enough.

Also onMicClick (keyboard): keep tap-toggle → onCenter.

**Big contributor #2 — STT empty → "Didn't catch that":** If Google returns empty for the user's speech (accent/short utterances), the mentor never responds. Mitigation: none from code; but we can make sure the recording quality is good (already 16k, echoCancellation). And give retry instruction (hint). Acceptable.

**Latency reductions to apply:**
- `_SPOKEN_TIMEOUT_SECONDS` 8 → 4.

Actually, wait. Let me reconsider reducing to 4. The user said "lower the latency as much as possible". The bound is a hard cap; healthy draws are 2-5.4s. With 4s, we lose model replies on draws 4-5.4s (fallback kicks in). Given the user's priority (actually respond, fast), and that the fallback is decent, 4s is reasonable. Alternative 5s keeps most healthy draws (~2-5s... up to 5). I'll pick **5s** — a good middle: keeps the typical healthy model draw, worst ~6s. Hmm. "as much as possible" → 4s. The model rarely wins anyway when throttled. Let me go 5s to retain model when quick, still ~6s worst. Ugh, decide: user priority = respond. 5s bound → worst ~6s total including HTTP. Under 6s from release to audio start is quite good. I'll go 5s.

Hmm, but actually my probe showed the fallback arrives at bound+overhead. With the LAST probe: 8s bound → 9.3s total (HTTP includes login? no, login separate; the tutor POST itself 9.3s → ~8s bound + ~1.3s parse/timeout overhead). With 5s bound → ~6.5s total. Good.

Also — what about the STT latency? recognize_google typically 0.5-1.5s. And TTS 1.4s for short. So total from release: STT(~1s) + tutor(≤6.5s) + TTS(~2-4s) ≈ 8-11s worst, ~5s best. That's "as low as possible" within this architecture.

Additional latency idea: for the STT step, the recording itself takes as long as the user holds. Can't reduce.

