input.content:
"""Repeated decision-grade measurements for super-120b on the live NIM endpoint.

Run A — interactive tutor turn, streaming, 3x (TTFT + total).
Run B — artifact resume, streaming, 4x (TTFT + total; EOF/drop counted).
Run C — artifact resume, NON-streaming exactly like _call_artifact uses, 3x (total).
All with enable_thinking:false under the 150s bound.
"""
import json
import sys
import time

import httpx

sys.path.insert(0, "backend")

KEY = None
for line in open("env", encoding="utf-8", errors="replace").read().splitlines():
    if line.startswith("NVIDIA_API_KEY="):
        KEY = line.split("=", 1)[1].strip()
BASE = "https://integrate.api.nvidia.com/v1/chat/completions"
H = {"Authorization": f"Bearer {KEY}", "Content-Type": "application/json"}
BOUND = 150
MODEL = "nvidia/nemotron-3-super-120b-a12b"

from app import copilot, genai  # noqa: E402

genai.NIM_KEY = KEY


def build_prompts():
    import httpx as hx
    c = hx.Client(base_url="http://127.0.0.1:8001", timeout=60)
    p = c.post("/api/auth/login", json={"email": "aisha@student.edu", "password": "demo1234"}).json()
    stud = p["student"]
    role = stud.get("target_role") or {}
    target_role = (role.get("title") or role.get("name") or "").strip() if isinstance(role, dict) else str(role or "").strip()
    ctx = copilot.build_context(stud, page="dashboard", country=p.get("country") or "",
                                location=p.get("location") or "")
    ctx_text = f"{ctx['label']} context:\n{ctx['context']}\nLanguage: English"
    calls = []

    def capture(system, user, **kwargs):
        calls.append((system, user))
        raise RuntimeError("capture-only")

    genai._call_nim = capture
    try:
        genai.tutor_reply(
            "Explain Docker volumes.", student_context=ctx_text, skill_name=None,
            target_role=target_role, tutor_id="sage", mode="chat", language="en",
            personality=None, conversation_memory=None, spoken=True,
        )
    except RuntimeError:
        pass
    t_sys, t_user = calls[0]
    verified = [v for v in (stud.get("verified_skills") or []) if isinstance(v, dict)]
    reported = [s for s in (stud.get("self_reported_skills") or []) if isinstance(s, dict)]
    name = p.get("display_name") or stud.get("name") or ""
    a_sys, a_user = genai._artifact_prompt(
        "resume", language="en", display_name=name, target_role=target_role,
        verified=verified, self_reported=reported,
        university=str(stud.get("university") or "").strip(),
        education_level=str(stud.get("education_level") or "").strip(),
    )
    return t_sys, t_user, a_sys, a_user


def base_payload(system, user, max_tokens, stream, thinking=False):
    p = {
        "model": MODEL, "stream": stream,
        "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
        "max_tokens": max_tokens, "temperature": 0.6, "top_p": 0.95,
    }
    if thinking is not None:
        p["chat_template_kwargs"] = {"enable_thinking": thinking}
    return p


def measure_stream(system, user, max_tokens):
    t0 = time.time()
    first_ttft = None
    content = ""
    finish = None
    status = None
    outcome = "ok"
    timeout = httpx.Timeout(15.0, connect=15.0, read=BOUND + 20)
    try:
        with httpx.Client(timeout=timeout) as c:
            with c.stream("POST", BASE, json=base_payload(system, user, max_tokens, True), headers=H) as r:
                status = r.status_code
                if status != 200:
                    return {"status": status, "elapsed": round(time.time() - t0, 1),
                            "body": r.read().decode("utf-8", "replace")[:160]}
                for line in r.iter_lines():
                    if not line or not line.startswith("data:"):
                        continue
                    d = line[5:].strip()
                    if d == "[DONE]":
                        break
                    try:
                        obj = json.loads(d)
                    except json.JSONDecodeError:
                        continue
                    ch = obj.get("choices") or [{}]
                    delta = ch[0].get("delta") or {}
                    finish = ch[0].get("finish_reason")
                    ck = delta.get("content")
                    if ck:
                        if first_ttft is None:
                            first_ttft = time.time() - t0
                        content += ck
    except httpx.TimeoutException:
        outcome = "timeout"
    except Exception as e:
        outcome = f"exc:{type(e).__name__}"
    total = time.time() - t0
    if not content and outcome == "ok":
        outcome = "empty_stream" if finish else f"EOF({finish})"
    return {
        "status": status, "ttft_ms": round(first_ttft * 1000) if first_ttft else None,
        "total_s": round(total, 1), "chars": len(content), "finish": finish, "outcome": outcome,
        "preview": content[:70].replace("\n", " "),
    }


def measure_nonstream(system, user, max_tokens):
    t0 = time.time()
    timeout = httpx.Timeout(15.0, connect=15.0, read=BOUND + 20)
    try:
        with httpx.Client(timeout=timeout) as c:
            r = c.post(BASE, json=base_payload(system, user, max_tokens, False), headers=H)
            total = time.time() - t0
            if r.status_code != 200:
                return {"status": r.status_code, "total_s": round(total, 1),
                        "body": r.text[:160]}
            msg = ((r.json().get("choices") or [{}])[0].get("message") or {})
            content = msg.get("content") or ""
            return {"status": 200, "total_s": round(total, 1), "chars": len(content),
                    "preview": content[:70].replace("\n", " "),
                    "reasoning_present": bool(msg.get("reasoning_content"))}
    except httpx.TimeoutException:
        return {"status": None, "total_s": round(time.time() - t0, 1), "outcome": "timeout_bounded"}
    except Exception as e:
        return {"status": None, "total_s": round(time.time() - t0, 1), "outcome": f"exc:{type(e).__name__}"}


def main():
    t_sys, t_user, a_sys, a_user = build_prompts()
    print(f"tutor prompt s={len(t_sys)}B u={len(t_user)}B ; resume prompt s={len(a_sys)}B u={len(a_user)}B")
    print("\n=== RUN A: interactive tutor turn, streaming, 3x (spoken budget 200) ===")
    for i in range(3):
        r = measure_stream(t_sys, t_user, 200)
        print(f"  [{i+1}] {json.dumps(r, ensure_ascii=False)}", flush=True)
        time.sleep(0.8)
    print("\n=== RUN B: artifact resume, streaming, 4x (1536) ===")
    for i in range(4):
        r = measure_stream(a_sys, a_user, 1536)
        print(f"  [{i+1}] {json.dumps(r, ensure_ascii=False)}", flush=True)
        time.sleep(0.8)
