    """Return (sample_rate, sample_width) from a PCM RIFF/WAVE header.
    Supports 16/24/32-bit PCM."""
    if len(wav_bytes) < 44:
        raise ValueError("WAV header too short")
    if wav_bytes[:4] != b"RIFF" or wav_bytes[8:12] != b"WAVE":
        raise ValueError("Not a valid RIFF/WAVE file")
    sample_rate = int.from_bytes(wav_bytes[24:28], "little")
    bits_per_sample = int.from_bytes(wav_bytes[34:36], "little")
    sample_width = bits_per_sample // 8
    if sample_width not in (2, 3, 4):
        raise ValueError(f"Unsupported sample width: {sample_width}")
    return sample_rate, sample_width

